-- 3. Upsert All Exercises
INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (1, 1, 'Standard Push-up', 'pushup', 'Standard Push-up', 'Классические отжимания', 'Классикалық еденнен сығылу', 'Horizontal pressing benchmark evaluating chest depth, scapular control, and plank core integrity.', 'Horizontal pressing benchmark evaluating chest depth, scapular control, and plank core integrity.', 'Фундаментальное упражнение для развития мышц груди, плечевого пояса и стабильности корпуса.', 'Кеуде бұлшықеттерін, иық белдеуін және дененің жалпы тұрақтылығын дамытатын негізгі жаттығу.', 'Pectoralis Major, Triceps, Anterior Deltoids', 'Pectoralis Major, Triceps, Anterior Deltoids', 'Большая грудная, трицепс, передняя дельта', 'Үлкен кеуде бұлшықеті, трицепс, алдыңғы дельта', 'Bodyweight', 'Bodyweight', 'Свой вес', 'Өз салмағы', 'Beginner', '1. Keep your head neutral and gaze at the floor.
2. Lower your chest toward the floor by bending elbows back at a 45° angle.
3. Descend until chest is 2-3 cm from the floor.
4. Push the floor away forcefully to return to full arm extension.', '1. Держите шею нейтрально, взгляд направлен в пол.
2. Опускайте грудь к полу, сгибая локти под углом 45 градусов к телу.
3. Опуститесь до касания пола грудью или 2-3 см от него.
4. Мощно вытолкните себя вверх до полного выпрямления рук.', '1. Мойынды түзу ұстап, еденге қараңыз.
2. Шынтақты денеге 45 градус бұрышпен бүгіп, кеудені еденге қарай түсіріңіз.
3. Кеуде еденнен 2-3 см қалғанша төмендеңіз.
4. Қолды толық жазып, еденнен жоғары қарай күшпен итеріліңіз.', 'Sagging lower back, flared elbows at 90°, craning neck downward, incomplete lockout.', 'Провисание таза в пояснице, разведение локтей на 90 градусов в стороны, задирание головы, неполная амплитуда.', 'Белдің төмен түсіп салбырауы, шынтақтың 90 градусқа жан-жаққа ашылуы, мойынды созу, қолды толық жазбау.', 'IODxDxX7oi4', 'https://www.youtube.com/watch?v=IODxDxX7oi4', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (2, 19, 'Barbell / Bodyweight Squat', 'squat', 'Barbell / Bodyweight Squat', 'Приседания со штангой / с собственным весом', 'Штангамен / өз салмағымен отырып-тұру', 'Foundational multi-joint lower body movement developing leg strength, hip mobility, and pelvic stability.', 'Foundational multi-joint lower body movement developing leg strength, hip mobility, and pelvic stability.', 'Базовое многосуставное упражнение для развития силы ног, подвижности тазобедренных суставов и стабильности корпуса.', 'Аяқ күшін, жамбас буынының қозғалғыштығын және дене тұрақтылығын дамытуға арналған негізгі жаттығу.', 'Quadriceps, Gluteus Maximus, Core Stabilizers', 'Quadriceps, Gluteus Maximus, Core Stabilizers', 'Квадрицепс, большая ягодичная, мышцы кора', 'Квадрицепс, үлкен бөксе бұлшықеті, кор', 'Bodyweight / Barbell', 'Bodyweight / Barbell', 'Свой вес / Штанга', 'Өз салмағы / Штанга', 'Intermediate', '1. Inhale deeply into your abdomen and brace your core.
2. Initiate descent by hinging at the hips and bending the knees simultaneously.
3. Lower down under control until hips descend parallel to or below knee line.
4. Drive powerfully through the midfoot to return to lockout.', '1. Сделайте глубокий вдох в живот и напрягите мышцы кора.
2. Начните движение с одновременного отведения таза назад и сгибания коленей.
3. Опуститесь под контролем до параллели бедер с полом или чуть ниже.
4. Мощно оттолкнитесь серединой стопы и вернитесь в исходное положение.', '1. Ішке терең тыныс алып, кор бұлшықеттерін қатайтыңыз.
2. Жамбасты артқа қарай жылжытып, тізені бүгуді қатар бастаңыз.
3. Сан еденге параллель болғанша немесе төменірек баяу отырыңыз.
4. Табанның ортасымен күшпен итеріліп, бастапқы қалыпқа оралыңыз.', 'Knees collapsing inward (valgus), heels lifting off floor, excessive forward torso lean, incomplete depth.', 'Сведение коленей внутрь (вальгус), отрыв пяток от пола, чрезмерный наклон корпуса вперед, недостаточная глубина.', 'Тізенің ішке қарай майысуы, өкшенің еденнен көтерілуі, дененің алға тым қатты еңкеюі, толық отырмау.', 'aclH2T8NY5I', 'https://www.youtube.com/watch?v=aclH2T8NY5I', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (3, 10, 'Dumbbell Bicep Curl', 'bicep_curl', 'Dumbbell Bicep Curl', 'Сгибание рук с гантелями на бицепс', 'Гантельмен бицепске қолды бүгу', 'Classic isolation movement building peak bicep hypertrophy and elbow flexion power.', 'Classic isolation movement building peak bicep hypertrophy and elbow flexion power.', 'Изолированное упражнение для максимального сокращения и гипертрофии двуглавой мышцы плеча.', 'Бицепстің күшін арттыруға және оны толық қатайтуға арналған оқшауланған жаттығу.', 'Biceps Brachii (Short & Long head), Brachialis', 'Biceps Brachii (Short & Long head), Brachialis', 'Двуглавая мышца плеча (бицепс), плечевая мышца', 'Қолдың екі басты бұлшықеті (бицепс), иық бұлшықеті', 'Dumbbells', 'Dumbbells', 'Гантели', 'Гантельдер', 'Beginner', '1. Keep your upper arms pinned stationary to your sides.
2. Curl the dumbbells upward while supinating your wrists (turning palms up).
3. Squeeze biceps hard at the peak of contraction.
4. Lower with a controlled 2-3 second eccentric descent.', '1. Зафиксируйте локти по бокам корпуса без смещения вперед.
2. Сгибайте руки в локтях, разворачивая кисти ладонями вверх (супинация).
3. Задержитесь и прожмите бицепс в верхней точке на 1 секунду.
4. Подконтрольно опустите гантели в течение 2-3 секунд.', '1. Шынтақты денеге жабыстырып, қозғалтпай ұстаңыз.
2. Алақанды жоғары қарай бұра отырып (супинация), гантельдерді жоғары көтеріңіз.
3. Ең жоғарғы нүктеде бицепсті 1 секунд қатайтыңыз.
4. Гантельдерді 2-3 секунд ішінде баяу төмен түсіріңіз.', 'Swinging torso for momentum, elbows drifting forward, dropping weight without eccentric control.', 'Раскачивание корпусом (читинг), увод локтей вперед или назад, бросание веса вниз без сопротивления.', 'Денемен екпін беру (читинг), шынтақты алға немесе артқа жылжыту, салмақты бақылаусыз тез тастай салу.', 'ykJmrZ5v0Oo', 'https://www.youtube.com/watch?v=ykJmrZ5v0Oo', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (4, 6, 'Overhead Shoulder Press', 'shoulder_press', 'Overhead Shoulder Press', 'Армейский жим стоя / Жим гантелей над головой', 'Гантельді / штанганы бастан асыра көтеру', 'Primary vertical pressing strength builder for total shoulder development and overhead scapular stability.', 'Primary vertical pressing strength builder for total shoulder development and overhead scapular stability.', 'Базовое вертикальное жимовое упражнение для силы плечевого пояса и стабильности лопаток.', 'Иық белдеуінің күшін және жауырын тұрақтылығын арттыруға арналған негізгі вертикаль жим жаттығуы.', 'Anterior & Lateral Deltoids, Triceps Brachii', 'Anterior & Lateral Deltoids, Triceps Brachii', 'Передняя и средняя дельта, трицепс', 'Алдыңғы және ортаңғы дельталар, трицепс', 'Dumbbells / Barbell', 'Dumbbells / Barbell', 'Гантели / Штанга', 'Гантельдер / Штанга', 'Intermediate', '1. Brace core and avoid overarching your lower back.
2. Press the weight vertically overhead in a smooth path until arms lock out.
3. Bring biceps close to ears at top lockout.
4. Lower smoothly back to collarbone level under control.', '1. Напрягите кор, исключите прогиб в пояснице.
2. Выжмите вес строго вверх над головой до полного выпрямления рук.
3. В верхней точке бицепсы находятся на одной линии с ушами.
4. Плавно верните снаряд к плечам по той же траектории.', '1. Корды қатайтып, белдің шамадан тыс бүгілуіне жол бермеңіз.
2. Салмақты қолдар толық жазылғанша бастан асыра тік жоғары көтеріңіз.
3. Жоғарғы нүктеде бицепстер құлақпен бір сызықта болуы тиіс.
4. Салмақты иық деңгейіне баяу түсіріңіз.', 'Hyper-extending lower back, pressing forward instead of overhead, asymmetrical lockout.', 'Сильный прогиб в пояснице, выжимание веса вперед вместо положения над головой, асимметричный жим.', 'Белдің шамадан тыс қайқаюы, салмақты бастан асырмай алға қарай итеру, қолдардың біркелкі жазылмауы.', '2yjwHevKmT0', 'https://www.youtube.com/watch?v=2yjwHevKmT0', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (5, 3, 'Standard Pull-up', 'pullup', 'Standard Pull-up', 'Подтягивания на перекладине', 'Турникке тартылу', 'Vertical pulling gold standard evaluating lat recruitment, scapular depression, and core stability.', 'Vertical pulling gold standard evaluating lat recruitment, scapular depression, and core stability.', 'Золотой стандарт вертикальной тяги для развития широчайших мышц спины и силы хвата.', 'Арқаның жалпақ бұлшықеттері мен қол күшін дамытатын вертикаль тартудың негізгі жаттығуы.', 'Latissimus Dorsi, Rhomboids, Biceps Brachii', 'Latissimus Dorsi, Rhomboids, Biceps Brachii', 'Широчайшие мышцы спины, ромбовидные, бицепс', 'Арқаның жалпақ бұлшықеттері, ромб тәрізді, бицепс', 'Bodyweight / Pull-up Bar', 'Bodyweight / Pull-up Bar', 'Свой вес / Перекладина', 'Өз салмағы / Турник', 'Advanced', '1. Retract and depress your shoulder blades.
2. Drive elbows down toward your hips while pulling chest to the bar.
3. Pull until your chin clearly clears the bar.
4. Lower with full control back to a complete dead hang.', '1. Начните движение со сведения и опускания лопаток вниз.
2. Направляйте локти вниз к талии, подтягивая грудь к перекладине.
3. Подтягивайтесь до тех пор, пока подбородок не окажется выше перекладины.
4. Плавно опуститесь в исходное положение полного виса.', '1. Жауырыныңызды төмен қарай жиырып қозғалысты бастаңыз.
2. Шынтақты төмен бағыттап, кеудеңізді турникке қарай тартыңыз.
3. Иегіңіз турниктен асқанша жоғары көтеріліңіз.
4. Баяу толық созылған қалыпқа дейін төмен түсіңіз.', 'Kipping legs, half repetitions, rounded shoulders at top, failure to reach full lockout at bottom.', 'Рывки ногами (киппинг), неполная амплитуда, задирание плеч к ушам, отсутствие полного виса внизу.', 'Аяқпен сермеп көтерілу (киппинг), жартылай тартылу, иықты құлаққа жақындату, төменде қолды толық жазбау.', 'eGo4IYlb45g', 'https://www.youtube.com/watch?v=eGo4IYlb45g', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (6, 1, 'Barbell Bench Press', 'barbell_bench_press', 'Barbell Bench Press', 'Жим штанги лежа', 'Жатып штанганы сығу', 'The foundational upper-body horizontal pressing strength and hypertrophy movement.', 'The foundational upper-body horizontal pressing strength and hypertrophy movement.', 'Базовое многосуставное жимовое движение для развития максимальной силы и объема грудных мышц.', 'Кеуде бұлшықеттерінің күші мен көлемін арттыруға арналған негізгі көпбуынды жим жаттығуы.', 'Pectoralis Major (Sternal & Clavicular)', 'Pectoralis Major (Sternal & Clavicular)', 'Большая грудная мышца (стернальная и ключичная части)', 'Үлкен кеуде бұлшықеті (төс және бұғана бөліктері)', 'Barbell & Bench', 'Barbell & Bench', 'Штанга и скамья', 'Штанга және орындық', 'Intermediate', '1. Unrack bar with arms locked over mid-chest.
2. Inhale, brace core, and lower bar in a slight arc to lower chest (nipple line).
3. Keep elbows tucked at 45-70 degrees.
4. Press bar powerfully back up to starting lockout.', '1. Снимите гриф и зафиксируйте над серединой груди.
2. Сделайте вдох, напрягите кор и плавно опустите гриф к нижней части груди.
3. Локти держите под углом 45-70 градусов к корпусу.
4. Мощно выжмите гриф вверх до полного выпрямления рук.', '1. Штанганы тіреуіштен алып, кеуде үстінде тік ұстаңыз.
2. Тыныс алып, штанганы кеуденің төменгі тұсына баяу түсіріңіз.
3. Шынтақты денеге 45-70 градус бұрышпен бағыттаңыз.
4. Қолды толық жазып, штанганы жоғары қарай күшпен итеріңіз.', 'Flaring elbows out to 90°, bouncing bar off sternum, raising hips/glutes off the bench, loose wrists.', 'Разведение локтей на 90° в стороны, отбив грифа от грудины, отрыв таза от скамьи, залом запястий.', 'Шынтақты 90° жан-жаққа ашу, штанганы кеудеге ұрып алу, бөксеңізді орындықтан көтеру, білекті қайыру.', 'rT7DgCr-3pg', 'https://www.youtube.com/watch?v=rT7DgCr-3pg', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (7, 1, 'Incline Dumbbell Press', 'incline_dumbbell_press', 'Incline Dumbbell Press', 'Жим гантелей на наклонной скамье', 'Көлбеу орындықта гантельді сығу', 'Targeted upper pectoral exercise using an incline angle for balanced bilateral chest development.', 'Targeted upper pectoral exercise using an incline angle for balanced bilateral chest development.', 'Акцентированное упражнение для развития верхнего отдела груди с глубокой растяжкой и независимой работой рук.', 'Кеуденің жоғарғы бөлігін дамытуға және екі қолдың теңгерімді күшін арттыруға арналған жаттығу.', 'Upper Pectoralis (Clavicular Head)', 'Upper Pectoralis (Clavicular Head)', 'Верхняя часть грудных мышц (ключичная головка)', 'Кеуде бұлшықетінің жоғарғы бөлігі (бұғана басы)', 'Dumbbells & Incline Bench', 'Dumbbells & Incline Bench', 'Гантели и наклонная скамья', 'Гантельдер және көлбеу орындық', 'Intermediate', '1. Press dumbbells up and slightly inward without clanking them together.
2. Lower dumbbells under control until you feel a comfortable stretch in upper chest.
3. Keep wrists directly stacked over elbows throughout.
4. Repeat with uniform tempo.', '1. Выжмите гантели вверх и слегка навстречу друг другу без соударения.
2. Плавно опустите гантели до ощущения комфортного растяжения в верхней части груди.
3. Держите запястья строго над локтями.
4. Повторите в плавном контролируемом темпе.', '1. Гантельдерді бір-біріне соқпай жоғары қарай сығыңыз.
2. Кеуденің жоғарғы бөлігі созылғанша гантельдерді баяу түсіріңіз.
3. Білектерді шынтақтың үстінде түзу ұстаңыз.
4. Бірқалыпты ырғақпен қайталаңыз.', 'Bench angle too steep (>45°) turning it into a shoulder press, dropping elbows too low, banging dumbbells at the top.', 'Слишком большой угол наклона (>45°), перегружающий дельты; чрезмерное опускание локтей; стук гантелей вверху.', 'Орындықты тым тік қойып иыққа салмақ түсіру (>45°); шынтақты тым төмен түсіру; гантельдерді соғу.', '8iPEnn-ltC8', 'https://www.youtube.com/watch?v=8iPEnn-ltC8', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (8, 1, 'Cable Chest Flyes', 'cable_chest_fly', 'Cable Chest Flyes', 'Сведение рук в кроссовере на грудь', 'Кроссоверде қолды қосу (кеуде)', 'Isolation movement delivering continuous resistance throughout full chest adduction.', 'Isolation movement delivering continuous resistance throughout full chest adduction.', 'Изолированное упражнение с постоянным натяжением для максимального пикового сокращения грудных мышц.', 'Кеуде бұлшықеттерін толық созуға және қатайтуға арналған тұрақты қарсылықты оқшауланған жаттығу.', 'Pectoralis Major (Inner & Mid Sternal)', 'Pectoralis Major (Inner & Mid Sternal)', 'Большая грудная мышца (стернальная часть)', 'Үлкен кеуде бұлшықеті (ортаңғы бөлігі)', 'Cable Machine / Dual Pulleys', 'Cable Machine / Dual Pulleys', 'Блочный тренажер (кроссовер)', 'Блоктық тренажер (кроссовер)', 'Beginner', '1. Maintain a slight, fixed bend in your elbows.
2. Bring hands together in a wide hugging arc across your chest.
3. Squeeze pectorals firmly at peak meeting point for 1 second.
4. Open arms with control until a deep stretch is achieved.', '1. Зафиксируйте легкий изгиб в локтях на протяжении всего подхода.
2. Сводите рукояти по широкой дуге перед грудью, словно обнимаете большое дерево.
3. Задержитесь и прожмите грудные мышцы в точке сведения на 1 секунду.
4. Плавно разведите руки до глубокого растяжения.', '1. Шынтақтағы аздаған бүгілісті жаттығу соңына дейін сақтаңыз.
2. Кеуде тұсында қолдарды доға бойымен алға қарай қосыңыз.
3. Қолдар қосылған кезде кеудені 1 секунд қатайтыңыз.
4. Кеуде толық созылғанша қолды баяу екі жаққа ашыңыз.', 'Bending and extending elbows into a press, using body swing momentum, overextending shoulders backward.', 'Превращение сведения в жим со сгибанием локтей, раскачка корпусом, чрезмерный увод локтей назад за спину.', 'Қозғалысты жимге айналдырып шынтақты бүгу, денемен тербелу, иықты артқа тым қатты қайыру.', 'Iwe6AmxVf7o', 'https://www.youtube.com/watch?v=Iwe6AmxVf7o', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (9, 1, 'Pec Deck Machine Flye', 'pec_deck_fly', 'Pec Deck Machine Flye', 'Сведение рук в тренажере Бабочка (Pec Deck)', 'Тренажерде қолды қосу (Көбелек / Pec Deck)', 'Guided isolation machine isolating chest fibers without excessive shoulder stabilizer demand.', 'Guided isolation machine isolating chest fibers without excessive shoulder stabilizer demand.', 'Безопасное изолированное упражнение на тренажере с заданной траекторией для глубокой проработки груди.', 'Кеуде бұлшықеттерін қауіпсіз және тиімді қатайтуға арналған арнайы тренажер жаттығуы.', 'Pectoralis Major (Sternal & Costal)', 'Pectoralis Major (Sternal & Costal)', 'Большая грудная мышца', 'Үлкен кеуде бұлшықеті', 'Pec Deck Machine', 'Pec Deck Machine', 'Тренажер Бабочка', 'Көбелек тренажеры', 'Beginner', '1. Grip handles with elbows slightly bent.
2. Bring handles together in front of your chest under smooth control.
3. Hold peak contraction for 1 second.
4. Slowly return handles until chest is comfortably stretched.', '1. Возьмитесь за рукояти, слегка согнув руки в локтях.
2. Плавно сведите рукояти перед собой силой грудных мышц.
3. Зафиксируйте пиковое сокращение на 1 секунду.
4. Медленно вернитесь назад до приятного растяжения.', '1. Тұтқаларды ұстап, шынтақты сәл бүгіңіз.
2. Кеуде бұлшықетінің күшімен тұтқаларды алға қарай жиырыңыз.
3. 1 секунд толық қатайтылған күйде ұстаңыз.
4. Кеуде созылғанша баяу артқа қайтыңыз.', 'Lifting shoulders toward ears, letting weight stack slam, losing back contact with pad.', 'Подъем плеч к ушам, резкий бросок весового стека, отрыв спины от спинки тренажера.', 'Иықты көтеру, салмақты тастай салу, арқаны тіреуіштен ажырату.', 'eGjt4lk6g34', 'https://www.youtube.com/watch?v=eGjt4lk6g34', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (10, 1, 'Chest Dips', 'dips_chest', 'Chest Dips', 'Отжимания на брусьях с акцентом на грудь', 'Брусьяда сығылу (кеудеге бағытталған)', 'Potent multi-joint compound movement developing lower chest mass and lock-out strength.', 'Potent multi-joint compound movement developing lower chest mass and lock-out strength.', 'Мощное базовое упражнение с собственным весом для прокачки низа груди и трицепсов.', 'Кеуденің төменгі бөлігі мен трицепсті дамытуға арналған қуатты базалық жаттығу.', 'Pectoralis Major (Lower & Sternal)', 'Pectoralis Major (Lower & Sternal)', 'Нижняя и стернальная часть грудных мышц', 'Кеуде бұлшықетінің төменгі бөлігі', 'Dip Bars / Parallel Bars', 'Dip Bars / Parallel Bars', 'Параллельные брусья', 'Параллель брустар', 'Advanced', '1. Maintain the forward torso lean throughout the rep.
2. Lower body smoothly until shoulders descend below elbow level (90° elbow bend).
3. Feel a deep stretch in lower chest.
4. Press back up powerfully without standing fully vertical.', '1. Сохраняйте наклон корпуса вперед на протяжении всего повторения.
2. Плавно опускайтесь вниз до угла 90° в локтях.
3. Почувствуйте растяжение в нижней части груди.
4. Мощно выжмите себя вверх, сохраняя наклон.', '1. Жаттығу бойы денені алға еңкейткен күйде ұстаңыз.
2. Шынтақ 90° бүгілгенше денеңізді баяу төмен түсіріңіз.
3. Кеуденің төменгі бөлігі созылғанын сезініңіз.
4. Денені жоғары қарай күшпен итеріп бастапқы қалыпқа келіңіз.', 'Staying too upright (shifts tension solely to triceps), dropping too fast, half-range reps, swinging legs.', 'Вертикальное положение корпуса (уводит нагрузку в трицепс), резкое падение вниз, неполная амплитуда, раскачка.', 'Денені тік ұстап трицепске салмақ түсіру, тез құлап түсу, жартылай орындау, аяқпен сермелу.', '2z8JmcrW-As', 'https://www.youtube.com/watch?v=2z8JmcrW-As', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (11, 2, 'Barbell Bent-Over Row', 'barbell_bent_row', 'Barbell Bent-Over Row', 'Тяга штанги в наклоне', 'Еңкейіп штанганы тарту', 'Foundational compound horizontal pull building mid-back thickness and posterior chain endurance.', 'Foundational compound horizontal pull building mid-back thickness and posterior chain endurance.', 'Базовое горизонтальное тяговое движение для мощного развития толщины спины и широчайших.', 'Арқаның қалыңдығы мен күшін арттыруға арналған негізгі горизонталь тарту жаттығуы.', 'Latissimus Dorsi, Rhomboids, Mid-Trapezius', 'Latissimus Dorsi, Rhomboids, Mid-Trapezius', 'Широчайшие мышцы, ромбовидные, средняя трапеция', 'Жалпақ бұлшықеттер, ромб тәрізді, ортаңғы трапеция', 'Barbell', 'Barbell', 'Штанга', 'Штанга', 'Intermediate', '1. Drive elbows back toward ceiling, pulling bar smoothly to lower ribcage/navel.
2. Retract scapulae and squeeze back muscles hard at the top.
3. Lower bar under control with a 2-second eccentric phase.
4. Keep spine neutral and avoid jerky upright bouncing.', '1. Тяните штангу к низу живота, ведя локти вдоль корпуса вверх и назад.
2. Сведите лопатки и максимально напрягите мышцы спины в верхней точке.
3. Плавно опустите гриф вниз за 2 секунды до полного растяжения широчайших.
4. Сохраняйте спину ровной без рывков корпусом.', '1. Шынтақты артқа қарай бағыттап, штанганы іштің төменгі тұсына тартыңыз.
2. Жоғарғы нүктеде жауырынды жиырып, арқа бұлшықеттерін қатайтыңыз.
3. Штанганы 2 секунд ішінде баяу төмен түсіріңіз.
4. Арқаны түзу ұстап, селкілдемей орындаңыз.', 'Rounding lumbar spine, standing up too vertical on each rep, jerking torso for momentum.', 'Округление поясницы (горб), выпрямление корпуса вверх при рывке, бросок веса вниз.', 'Белді бүкірейту, әр ретте денені тік көтеріп кету, салмақты екпінмен жұлып тарту.', '6TSP13ndbJg', 'https://www.youtube.com/watch?v=6TSP13ndbJg', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (12, 3, 'Wide-Grip Lat Pulldown', 'lat_pulldown', 'Wide-Grip Lat Pulldown', 'Тяга верхнего блока к груди', 'Жоғарғы блокты кеудеге тарту', 'Premier vertical pulling machine exercise for widening the lats with scalable load.', 'Premier vertical pulling machine exercise for widening the lats with scalable load.', 'Классическое упражнение на тренажере для формирования V-образной спины и ширины широчайших.', 'Арқаның V-тәрізді енін кеңейтуге және бұлшықеттерді дамытуға арналған классикалық жаттығу.', 'Latissimus Dorsi (Outer & Lower)', 'Latissimus Dorsi (Outer & Lower)', 'Широчайшие мышцы спины', 'Арқаның жалпақ бұлшықеттері', 'Cable Lat Pulldown Machine', 'Cable Lat Pulldown Machine', 'Тренажер тяги верхнего блока', 'Жоғарғы блок тренажеры', 'Beginner', '1. Depress shoulder blades down first.
2. Pull bar smoothly down to upper chest/collarbone, driving elbows down and back.
3. Squeeze lats hard at bottom for 1 second.
4. Control the ascent until arms and lats are fully stretched overhead.', '1. Опустите плечи и лопатки вниз.
2. Тяните рукоять к верхней части груди, направляя локти вниз и назад.
3. Зафиксируйте пиковое сокращение внизу на 1 секунду.
4. Медленно верните рукоять вверх до полного растяжения спины.', '1. Алдымен жауырынды төмен қарай жиырыңыз.
2. Шынтақты төмен бағыттап, тұтқаны кеуденің жоғарғы жағына тартыңыз.
3. Төменгі нүктеде арқаны 1 секунд қатайтыңыз.
4. Қолдар мен арқа толық созылғанша тұтқаны баяу жоғары көтеріңіз.', 'Leaning back excessively (>45° turning it into a row), pulling behind neck, letting shoulders rise into ears.', 'Сильный наклон назад (>45°), превращающий тягу в горизонтальную; тяга за голову; подъем плеч к ушам.', 'Артқа тым қатты шалқаю (>45°), желкеге қарай тарту, иықты құлаққа жақындату.', 'CAwf7n6Luuc', 'https://www.youtube.com/watch?v=CAwf7n6Luuc', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (13, 4, 'Cable Face Pull', 'face_pull', 'Cable Face Pull', 'Тяга каната к лицу (Face Pull)', 'Канатты бетке тарту (Face Pull)', 'Key posture-correcting exercise building rear delts, upper back thickness, and shoulder health.', 'Key posture-correcting exercise building rear delts, upper back thickness, and shoulder health.', 'Лучшее упражнение для коррекции осанки, укрепления задней дельты и здоровья плечевых суставов.', 'Дене түзулігін жақсартуға, артқы дельта мен иық буындарының саулығын арттыруға арналған жаттығу.', 'Rear Deltoids, Rhomboids, External Rotators, Traps', 'Rear Deltoids, Rhomboids, External Rotators, Traps', 'Задние дельты, ромбовидные, вращательная манжета, трапеции', 'Артқы дельталар, ромб тәрізді, айналдырушы манжета, трапеция', 'Cable Machine & Rope Attachment', 'Cable Machine & Rope Attachment', 'Блочный тренажер и канатная рукоять', 'Блоктық тренажер және арқан тұтқасы', 'Beginner', '1. Pull rope towards bridge of nose or forehead.
2. Externally rotate shoulders by driving hands back past your ears.
3. Squeeze shoulder blades and hold for 1 full second.
4. Slowly return weight with full eccentric control.', '1. Тяните канат к уровню переносицы/лба.
2. В конце движения разворачивайте плечи наружу, уводя кисти за уши (двойной бицепс).
3. Максимально сведите лопатки и удержите 1 секунду.
4. Плавно вернитесь в исходное положение.', '1. Арқанды мұрын немесе маңдай деңгейіне қарай тартыңыз.
2. Қозғалыс соңында иықты сыртқа айналдырып, қолды құлақтан асырыңыз.
3. Жауырынды жиырып, 1 секунд ұстап тұрыңыз.
4. Бастапқы қалыпқа баяу қайтыңыз.', 'Using excessive body momentum, pulling down into chest rather than face, dropping elbows below wrists.', 'Тяга корпусом с раскачкой, тяга вниз к груди вместо лица, опускание локтей ниже запястий.', 'Денемен екпін беру, бетке емес кеудеге тарту, шынтақты білектен төмен түсіру.', 'rep-qVOkqgk', 'https://www.youtube.com/watch?v=rep-qVOkqgk', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (14, 5, '45° Back Hyperextension', 'back_hyperextension', '45° Back Hyperextension', 'Гиперэкстензия на римском стуле 45°', '45° римдік орындықта гиперэкстензия', 'Direct lower back strengthening drill reinforcing spinal extension and posterior chain resilience.', 'Direct lower back strengthening drill reinforcing spinal extension and posterior chain resilience.', 'Одно из лучших упражнений для укрепления поясничного отдела спины, ягодиц и профилактики травм.', 'Бел бұлшықеттерін, бөксе мен омыртқа саулығын нығайтуға арналған ең тиімді жаттығу.', 'Erector Spinae (Lower Back), Gluteus Maximus', 'Erector Spinae (Lower Back), Gluteus Maximus', 'Разгибатели спины (поясница), большая ягодичная', 'Арқа жазғыштары (бел), үлкен бөксе бұлшықеті', '45° Hyperextension Bench', '45° Hyperextension Bench', 'Скамья для гиперэкстензии 45°', '45° гиперэкстензия орындығы', 'Beginner', '1. Hinge forward at hips with a flat neutral back.
2. Lower torso until hips reach 90° flexion.
3. Engage glutes and erectors to raise torso until body forms a straight line.
4. Pause at peak without hyperextending backward.', '1. Плавно наклонитесь вперед в тазобедренных суставах с ровной спиной.
2. Опуститесь до угла 90° в тазу.
3. Напряжением ягодиц и поясницы поднимите корпус до прямой линии с ногами.
4. Задержитесь в верхней точке, избегая избыточного переразгибания назад.', '1. Арқаны түзу ұстап, жамбастан алға қарай баяу еңкейіңіз.
2. Жамбас 90° бүгілгенше төмендеңіз.
3. Бөксе мен бел бұлшықеттерін жиырып, денені түзу сызыққа дейін көтеріңіз.
4. Артқа шамадан тыс қайқыймай, жоғарғы нүктеде тоқтаңыз.', 'Hyperextending and arching backward excessively at the top, rounding lumbar spine into a hump.', 'Чрезмерное закидывание корпуса назад вверху (переразгибание поясницы), сильное скручивание спины горбом.', 'Жоғарыда белді шамадан тыс артқа қайқайту, омыртқаны бүкірейту.', 'ph3pddpKzzw', 'https://www.youtube.com/watch?v=ph3pddpKzzw', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (15, 8, 'Dumbbell Lateral Raise', 'dumbbell_lateral_raise', 'Dumbbell Lateral Raise', 'Махи гантелями в стороны', 'Гантельді екі жаққа көтеру', 'Premier deltoid isolation exercise building lateral shoulder width and 3D silhouette.', 'Premier deltoid isolation exercise building lateral shoulder width and 3D silhouette.', 'Главное изолирующее упражнение для расширения плеч и акцентированной накачки средних дельт.', 'Иықты кеңейтуге және ортаңғы дельтаны қатайтуға арналған негізгі жаттығу.', 'Lateral Deltoids (Middle Head)', 'Lateral Deltoids (Middle Head)', 'Средняя дельтовидная мышца', 'Ортаңғы дельта бұлшықеті', 'Dumbbells', 'Dumbbells', 'Гантели', 'Гантельдер', 'Beginner', '1. Lead with elbows and raise arms out to sides in scapular plane (slight 20-30° forward angle).
2. Lift until dumbbells reach shoulder height (parallel to floor).
3. Pause briefly at peak contraction.
4. Lower with 2-second control without letting dumbbells slam together.', '1. Поднимайте руки через стороны, ведя движение локтями в плоскости лопаток (чуть вперед на 20-30°).
2. Поднимите гантели до уровня плеч параллельно полу.
3. Зафиксируйте пиковое напряжение на доли секунды.
4. Плавно опустите за 2 секунды, не сводя гантели вплотную перед собой.', '1. Шынтақты жетекші етіп, қолды екі жаққа қарай көтеріңіз (сәл алға 20-30°).
2. Гантельдер иық деңгейіне жеткенше көтеріңіз.
3. Жоғарғы нүктеде бұлшықетті қатайтыңыз.
4. Гантельдерді 2 секундта баяу төмен түсіріңіз.', 'Swinging torso/using leg drive, raising above shoulder plane shrugging traps, bent wrists pointing up.', 'Импульс ногами и раскачка корпусом, задирание рук выше плеч со шрагами трапеции, кисти выше локтей.', 'Денемен және аяқпен серпілу, қолды иықтан асыра көтеріп трапецияға салмақ түсіру, білекті шынтақтан жоғары көтеру.', '3VcKaXpzqRo', 'https://www.youtube.com/watch?v=3VcKaXpzqRo', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (16, 7, 'Pike Push-up', 'pike_pushup', 'Pike Push-up', 'Отжимания домиком (Pike Push-up)', 'Бұрыш жасап сығылу (Pike Push-up)', 'Bodyweight vertical pressing movement targeting front deltoids and scapular upward rotation.', 'Bodyweight vertical pressing movement targeting front deltoids and scapular upward rotation.', 'Эффективное упражнение с собственным весом для прокачки передних дельт и подготовки к стойке на руках.', 'Алдыңғы дельтаны қатайтуға және қолмен тұруға дайындалуға арналған өз салмағымен жасалатын жаттығу.', 'Anterior Deltoids, Clavicular Pectoralis', 'Anterior Deltoids, Clavicular Pectoralis', 'Передние дельты, верх груди', 'Алдыңғы дельталар, кеуденің жоғарғы жағы', 'Bodyweight', 'Bodyweight', 'Свой вес', 'Өз салмағы', 'Intermediate', '1. Lower crown of head forward and down in a tripod triangle ahead of your hands.
2. Descend until forehead lightly taps the floor.
3. Push back and up diagonally to return to the piked start position.
4. Keep hips elevated throughout.', '1. Опускайте голову вперед по диагонали перед ладонями, образуя треугольник.
2. Коснитесь лбом пола под контролем.
3. Вытолкните себя назад и вверх по диагонали в исходную позу домика.
4. Держите таз высоко поднятым на протяжении всего движения.', '1. Басты алақандардың алдына қарай диагональ бойынша түсіріңіз.
2. Маңдай еденге жеңіл тигенше төмендеңіз.
3. Қолмен күшпен итеріліп, бастапқы бұрыш қалпына қайтыңыз.
4. Жамбасты үнемі жоғары көтеріп ұстаңыз.', 'Letting hips drop into a standard push-up, flaring elbows out, craning neck backwards.', 'Опускание таза вниз (превращение в обычные отжимания), разведение локтей в стороны.', 'Жамбасты төмен түсіріп кәдімгі сығылуға айналдыру, шынтақты жан-жаққа ашу.', 'sposDXWEB0A', 'https://www.youtube.com/watch?v=sposDXWEB0A', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (17, 9, 'Rear Delt Machine Flye', 'rear_delt_fly', 'Rear Delt Machine Flye', 'Разведение рук в тренажере на задние дельты (Reverse Pec Deck)', 'Тренажерде қолды артқа ашу (артқы дельта)', 'Pure isolated posterior shoulder abduction building round 3D delts and scapular stability.', 'Pure isolated posterior shoulder abduction building round 3D delts and scapular stability.', 'Изолированное упражнение для прицельной прокачки задних пучков дельт с надежной фиксацией корпуса.', 'Артқы дельтаны оқшаулап қатайтуға арналған ыңғайлы және тиімді тренажер жаттығуы.', 'Posterior Deltoids (Rear Head)', 'Posterior Deltoids (Rear Head)', 'Задняя часть дельтовидной мышцы', 'Артқы дельта бұлшықеті', 'Reverse Pec Deck Machine', 'Reverse Pec Deck Machine', 'Тренажер обратная бабочка', 'Кері көбелек тренажеры', 'Beginner', '1. Keep a soft bend in elbows.
2. Drive handles outward and backward horizontally using rear delts.
3. Squeeze shoulder blades together at end range for 1 second.
4. Return smoothly to starting position before weights touch.', '1. Сохраняйте легкий изгиб в локтях.
2. Разводите рукояти назад силой задних дельт строго в горизонтальной плоскости.
3. Прожмите задние дельты в конечной точке на 1 секунду.
4. Плавно вернитесь вперед, не допуская соударения весовых плиток.', '1. Шынтақты сәл бүгілген күйде ұстаңыз.
2. Тұтқаларды артқа қарай көлденең жазықтықта ашыңыз.
3. Артқы нүктеде бұлшықеттерді 1 секунд қатайтыңыз.
4. Салмақты соқпай, баяу алға қайтыңыз.', 'Shrugging shoulders upward, bending elbows past 90 degrees turning it into a row, bouncing weight stack.', 'Подъем плеч к ушам (подключение трапеции), сильное сгибание локтей (превращение в тягу).', 'Иықты көтеру, шынтақты тым қатты бүгу, салмақты екпінмен жұлу.', 'v_ZoxM3Lw0E', 'https://www.youtube.com/watch?v=v_ZoxM3Lw0E', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (18, 13, 'Barbell Shrug', 'barbell_shrug', 'Barbell Shrug', 'Шраги со штангой стоя', 'Штангамен шраги (трапеция)', 'High-load scapular elevation builder strengthening upper traps and neck support.', 'High-load scapular elevation builder strengthening upper traps and neck support.', 'Базовое движение для изолированного развития верхней части трапеции и укрепления шеи.', 'Жоғарғы трапецияны және мойын бұлшықеттерін күшейтуге арналған негізгі жаттығу.', 'Upper Trapezius', 'Upper Trapezius', 'Верхняя часть трапециевидной мышцы', 'Трапецияның жоғарғы бөлігі', 'Barbell', 'Barbell', 'Штанга', 'Штанга', 'Beginner', '1. Elevate shoulders straight up toward your ears in a pure vertical vector.
2. Squeeze traps at top of contraction for 1.5 seconds.
3. Lower bar smoothly under control to full stretch.
4. Do NOT roll shoulders in circles.', '1. Поднимайте плечи строго вертикально вверх к ушам.
2. Максимально сожмите трапеции в верхней точке и задержитесь на 1.5 секунды.
3. Плавно опустите плечи вниз до полного растяжения.
4. Категорически избегайте вращения плечами по кругу.', '1. Иықты тік жоғары қарай құлаққа қарай көтеріңіз.
2. Жоғарғы нүктеде трапецияны 1.5 секунд қатты жиырыңыз.
3. Штанганы баяу төмен түсіріңіз.
4. Иықты дөңгелетіп айналдырмаңыз.', 'Rolling shoulders in circles (injures rotator cuff), bending elbows into a curl, using knee bounce.', 'Вращение плечами по кругу (травмирует плечевые суставы), сгибание рук в локтях, помощь ногами.', 'Иықты дөңгелетіп айналдыру (буынға зиян), шынтақты бүгу, аяқпен серпілу.', 'g6qbq4Sq138', 'https://www.youtube.com/watch?v=g6qbq4Sq138', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (19, 14, 'Isometric Neck Strengthening', 'neck_isometric_flexion_extension', 'Isometric Neck Strengthening', 'Изометрическое укрепление мышц шеи', 'Мойын бұлшықеттерін изометриялық нығайту', 'Safe isometric cervical conditioning protecting against impact and stabilizing neck posture.', 'Safe isometric cervical conditioning protecting against impact and stabilizing neck posture.', 'Безопасное статическое укрепление шейного отдела для защиты от травм и коррекции положения головы.', 'Мойын омыртқасын жарақаттан қорғауға және бастың түзулігін қалыптастыруға арналған қауіпсіз жаттығу.', 'Sternocleidomastoid, Cervical Extensors', 'Sternocleidomastoid, Cervical Extensors', 'Грудино-ключично-сосцевидная, разгибатели шеи', 'Мойынды бұрушы және жазушы бұлшықеттер', 'Bodyweight / Hand Resistance', 'Bodyweight / Hand Resistance', 'Свой вес / сопротивление руками', 'Өз салмағы / қол қарсылығы', 'Beginner', '1. Press head gently into palm while matching with equal hand resistance (no head movement).
2. Maintain steady contraction for 6-10 seconds.
3. Relax for 3 seconds and repeat across flexion, extension, and lateral vectors.
4. Keep breathing calmly.', '1. Плавно давите головой в ладонь, удерживая голову абсолютно неподвижной силой рук.
2. Удерживайте статическое напряжение 6-10 секунд.
3. Расслабьтесь на 3 секунды и повторите вперед, назад и в стороны.
4. Дышите ровно без задержки дыхания.', '1. Басты қозғалтпай, алақанға қарай бірқалыпты күшпен басыңыз.
2. Статикалық күшті 6-10 секунд ұстап тұрыңыз.
3. 3 секунд демалып, алға, артқа және бүйірге қайталаңыз.
4. Бірқалыпты тыныс алыңыз.', 'Jerking forcefully, holding breath, forcing neck through extreme painful angles.', 'Резкие рывки шеей, задержка дыхания (эффект Вальсальвы), чрезмерное давление руками.', 'Мойынды жұлқып қозғалту, тынысты тоқтату, шамадан тыс қатты басу.', 'Y4p7Z1R17fI', 'https://www.youtube.com/watch?v=Y4p7Z1R17fI', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (20, 10, 'Barbell Bicep Curl', 'barbell_bicep_curl', 'Barbell Bicep Curl', 'Подъем штанги на бицепс стоя', 'Тұрып штанганы бицепске көтеру', 'Fundamental bilateral arm flexion builder allowing maximal overload for bicep mass.', 'Fundamental bilateral arm flexion builder allowing maximal overload for bicep mass.', 'Главное базовое упражнение для наращивания максимальной массы и силы двуглавой мышцы плеча.', 'Бицепстің күші мен көлемін арттыруға арналған негізгі штанга жаттығуы.', 'Biceps Brachii', 'Biceps Brachii', 'Двуглавая мышца плеча (бицепс)', 'Қолдың екі басты бұлшықеті (бицепс)', 'Barbell / EZ Bar', 'Barbell / EZ Bar', 'Штанга / EZ-гриф', 'Штанга / EZ-гриф', 'Beginner', '1. Curl the barbell up toward shoulder height by flexing at the elbows.
2. Keep upper arms completely stationary.
3. Squeeze biceps hard at top contraction for 1 second.
4. Lower the bar smoothly under a 3-second eccentric tempo.', '1. Сгибая руки в локтях, поднимите штангу по дуге к уровню плеч.
2. Сохраняйте плечевые кости строго неподвижными.
3. Максимально сожмите бицепсы в верхней точке на 1 секунду.
4. Плавно опустите гриф вниз за 3 секунды.', '1. Шынтақты бүгіп, штанганы иық деңгейіне қарай көтеріңіз.
2. Қолдың жоғарғы бөлігін қозғалтпай ұстаңыз.
3. Жоғарғы нүктеде бицепсті 1 секунд қатайтыңыз.
4. Штанганы 3 секунд ішінде баяу төмен түсіріңіз.', 'Swinging torso back and forth, drifting elbows forward, incomplete extension at the bottom.', 'Раскачивание корпусом назад, увод локтей вперед, неполное разгибание рук внизу.', 'Денемен алға-артқа тербелу, шынтақты алға жылжыту, төменде қолды толық жазбау.', 'ykJmrZ5v0Oo', 'https://www.youtube.com/watch?v=ykJmrZ5v0Oo', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (21, 10, 'Dumbbell Hammer Curl', 'hammer_curl', 'Dumbbell Hammer Curl', 'Молотковые сгибания с гантелями (Hammer Curls)', 'Балға тәрізді гантель көтеру (Hammer Curls)', 'Neutral-grip flexion drill maximizing brachialis recruitment for overall upper arm thickness.', 'Neutral-grip flexion drill maximizing brachialis recruitment for overall upper arm thickness.', 'Сгибания рук нейтральным хватом для прокачки плечелучевой мышцы и визуальной толщины рук.', 'Қолдың қалыңдығы мен ұстау күшін арттыруға арналған бейтарап ұстаумен жасалатын жаттығу.', 'Brachialis, Brachioradialis (Forearms)', 'Brachialis, Brachioradialis (Forearms)', 'Плечевая мышца (брахиалис), плечелучевая мышца', 'Иық бұлшықеті (брахиалис), иық-кәрі жілік бұлшықеті', 'Dumbbells', 'Dumbbells', 'Гантели', 'Гантельдер', 'Beginner', '1. Keep palms facing inward throughout the entire repetition.
2. Curl dumbbells upward toward shoulders.
3. Squeeze forearms and brachialis at the top.
4. Lower smoothly with 2-second resistance.', '1. Сохраняйте нейтральный хват (ладони внутрь) на всем протяжении движения.
2. Поднимите гантели к плечам силой рук.
3. Зафиксируйте пиковое напряжение вверху.
4. Плавно опустите гантели вниз за 2 секунды.', '1. Алақанды ішке қаратқан күйде жаттығу соңына дейін сақтаңыз.
2. Гантельдерді иыққа қарай көтеріңіз.
3. Жоғарғы нүктеде бұлшықеттерді қатайтыңыз.
4. 2 секундта баяу төмен түсіріңіз.', 'Twisting wrists, swinging hips for momentum, dropping dumbbells rapidly.', 'Разворот кистей (супинация), раскачка бедрами, резкий бросок веса вниз.', 'Білекті бұру, жамбаспен екпін беру, гантельді тез тастай салу.', 'zC3nLlEvin4', 'https://www.youtube.com/watch?v=zC3nLlEvin4', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (22, 11, 'Cable Tricep Pushdown', 'tricep_pushdown', 'Cable Tricep Pushdown', 'Разгибание рук на блоке на трицепс (с канатом)', 'Блокта қолды жазу (трицепс / канат)', 'Classic triceps isolation movement providing sustained tension and horseshoe definition.', 'Classic triceps isolation movement providing sustained tension and horseshoe definition.', 'Базовое изолирующее упражнение для прорисовки и накачки всех головок трицепса.', 'Трицепсті толық созуға және қатайтуға арналған негізгі оқшауланған жаттығу.', 'Triceps Brachii (Lateral & Medial Heads)', 'Triceps Brachii (Lateral & Medial Heads)', 'Трицепс (латеральная и медиальная головки)', 'Трицепс (сыртқы және ортаңғы бастары)', 'Cable Machine & Rope Attachment', 'Cable Machine & Rope Attachment', 'Блочный тренажер и канатная рукоять', 'Блоктық тренажер және арқан тұтқасы', 'Beginner', '1. Keep elbows pinned to your sides throughout.
2. Extend arms downward until fully locked out.
3. Flare rope ends outward slightly at the bottom for peak contraction.
4. Return smoothly to 90° elbow flexion.', '1. Зафиксируйте локти неподвижно по бокам корпуса.
2. Разгибайте руки вниз до полного выпрямления в локтях.
3. В нижней точке разведите концы каната в стороны для максимального пика.
4. Плавно вернитесь в исходное положение (угол 90° в локтях).', '1. Шынтақты денеге қозғалтпай жабыстырып ұстаңыз.
2. Қолды төмен қарай толық жазылғанша созыңыз.
3. Төменгі нүктеде арқанды екі жаққа сәл ашып, трицепсті қатайтыңыз.
4. Шынтақты 90° бүгіп баяу бастапқы қалыпқа қайтыңыз.', 'Letting elbows drift forward and backward, using body weight to lean over the bar, half-reps.', 'Хождение локтей вперед-назад, наваливание всем весом тела на рукоять, неполное разгибание.', 'Шынтақты алға-артқа жылжыту, бүкіл салмақпен үстіне құлау, қолды толық жазбау.', '2-LAMcpzODU', 'https://www.youtube.com/watch?v=2-LAMcpzODU', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (23, 11, 'EZ Bar Skull Crushers', 'skull_crushers', 'EZ Bar Skull Crushers', 'Французский жим лежа со штангой (Skull Crushers)', 'Жатып француз жимі (Skull Crushers)', 'Classic lying triceps extension isolating the long head with maximum eccentric stretch.', 'Classic lying triceps extension isolating the long head with maximum eccentric stretch.', 'Эффективное упражнение для максимального растяжения и развития длинной головки трицепса.', 'Трицепстің ұзын басын терең созуға және күшейтуге арналған классикалық жаттығу.', 'Triceps Brachii (Long Head Focus)', 'Triceps Brachii (Long Head Focus)', 'Длинная и медиальная головки трицепса', 'Трицепстің ұзын және ортаңғы бастары', 'EZ Bar & Flat Bench', 'EZ Bar & Flat Bench', 'EZ-штанга и горизонтальная скамья', 'EZ-штанга және жазық орындық', 'Intermediate', '1. Keep upper arms stationary angled back.
2. Bend elbows to lower the bar toward your forehead or crown of head.
3. Feel a deep stretch in the triceps.
4. Extend elbows powerfully back to the angled starting position.', '1. Удерживайте плечевые кости неподвижными под небольшим углом назад.
2. Сгибая только локти, опустите гриф к макушке головы.
3. Почувствуйте глубокое растяжение в трицепсах.
4. Разгибая локти, мощно верните гриф в исходную точку.', '1. Қолдың жоғарғы бөлігін артқа қарай қозғалтпай ұстаңыз.
2. Тек шынтақты бүгіп, штанганы маңдайға немесе төбеге қарай түсіріңіз.
3. Трицепстің созылғанын сезініңіз.
4. Шынтақты жазып, бастапқы қалыпқа күшпен қайтыңыз.', 'Flaring elbows outward, turning movement into a close-grip press by moving shoulders, dropping bar too fast.', 'Разведение локтей в стороны, превращение в жим узким хватом, резкое падение штанги к лицу.', 'Шынтақты жан-жаққа ашу, жаттығуды жимге айналдыру, штанганы бетке қарай тез құлату.', 'd_KZxkY_0cM', 'https://www.youtube.com/watch?v=d_KZxkY_0cM', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (24, 12, 'Heavy Farmer Carry', 'farmer_carry', 'Heavy Farmer Carry', 'Прогулка фермера с гантелями / гирями', 'Фермер жүрісі (гантельмен / гирмен)', 'Functional loaded carry building crushing grip strength, scapular endurance, and whole-body core stability.', 'Functional loaded carry building crushing grip strength, scapular endurance, and whole-body core stability.', 'Фундаментальное функциональное упражнение для развития железного хвата, трапеций и стабильности кора.', 'Қолдың мықты ұстау күшін, трапецияны және дененің тұрақтылығын дамытатын функционалды жаттығу.', 'Forearm Flexors, Grip Strength, Trapezius', 'Forearm Flexors, Grip Strength, Trapezius', 'Сгибатели предплечья, сила хвата, трапеции', 'Білек бүккіштері, ұстау күші, трапеция', 'Heavy Dumbbells / Kettlebells', 'Heavy Dumbbells / Kettlebells', 'Тяжелые гантели / гири', 'Ауыр гантельдер / гирлер', 'Beginner', '1. Maintain a tall posture with shoulders down and back.
2. Walk forward in a straight line with controlled, deliberate strides.
3. Keep core rigidly braced and prevent side-to-side torso sway.
4. Walk for prescribed distance or 30-45 seconds.', '1. Держите осанку идеально ровной, плечи расправлены и опущены.
2. Идите вперед ровным шагом по прямой линии.
3. Держите пресс напряженным, избегая раскачивания корпуса в стороны.
4. Пройдите намеченную дистанцию или 30-45 секунд под нагрузкой.', '1. Денені түзу ұстап, иықты артқа қарай жиырыңыз.
2. Түзу сызық бойымен нық, баяу қадамдармен алға жүріңіз.
3. Дененің екі жаққа шайқалмауын қадағалап, корды қатайтыңыз.
4. Белгіленген қашықтықты немесе 30-45 секунд бойы жүріңіз.', 'Slouching shoulders forward, wobbling torso, taking rushed uncontrolled running steps.', 'Сутулость плеч вперед, боковая раскачка туловища, слишком быстрые семенящие шаги.', 'Иықты алға бүкірейту, дененің шайқалуы, асығыс жүгіріп кету.', 'Fkzk_RqlXP0', 'https://www.youtube.com/watch?v=Fkzk_RqlXP0', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (25, 15, 'Hanging Leg Raise', 'hanging_leg_raise', 'Hanging Leg Raise', 'Подъем ног в висе на перекладине', 'Турникте аяқты көтеру', 'High-yield abdominal exercise targeting the lower rectus abdominis via active posterior pelvic tilt.', 'High-yield abdominal exercise targeting the lower rectus abdominis via active posterior pelvic tilt.', 'Мощное упражнение на пресс с глубоким подкручиванием таза в висе для проработки нижнего отдела пресса.', 'Іштің төменгі бұлшықеттерін толық қатайтуға және күшейтуге арналған турниктегі жаттығу.', 'Rectus Abdominis, Iliopsoas', 'Rectus Abdominis, Iliopsoas', 'Прямая мышца живота (низ пресса), подвздошно-поясничная', 'Тік іш бұлшықеті, мықын-бел бұлшықеті', 'Pull-up Bar', 'Pull-up Bar', 'Турник / перекладина', 'Турник', 'Intermediate', '1. Without swinging, raise legs smoothly toward the bar by curling pelvis upward.
2. Lift feet until parallel to floor (or higher towards the bar).
3. Squeeze abs firmly at peak contraction for 1 second.
4. Lower legs under full eccentric control without swinging backward.', '1. Без раскачки поднимите ноги вверх, подкручивая таз к ребрам.
2. Поднимите стопы до параллели с полом или выше.
3. Сожмите пресс на 1 секунду в верхней точке.
4. Медленно опустите ноги вниз, не допуская обратного раскачивания.', '1. Тербелмей, жамбасты бүгіп, аяқтарды жоғары қарай көтеріңіз.
2. Аяқты еденге параллель немесе одан жоғары деңгейге көтеріңіз.
3. Жоғарғы нүктеде іш бұлшықеттерін 1 секунд қатайтыңыз.
4. Аяқты баяу төмен түсіріңіз.', 'Using swinging momentum, raising legs solely via hip flexors without curling pelvis, dropping legs fast.', 'Раскачивание телом, подъем только за счет сгибателей бедра без подкручивания таза, бросок ног вниз.', 'Денемен тербеліп сермелу, жамбасты бүкпей тек аяқты көтеру, аяқты тез тастай салу.', 'hdng3Nm1x_E', 'https://www.youtube.com/watch?v=hdng3Nm1x_E', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (26, 17, 'Forearm Plank', 'forearm_plank', 'Forearm Plank', 'Классическая планка на предплечьях', 'Шынтаққа сүйеніп планка тұру', 'The foundational anti-extension isometric core exercise for spinal stiffness and posture.', 'The foundational anti-extension isometric core exercise for spinal stiffness and posture.', 'Фундаментальное статическое упражнение против разгибания позвоночника для создания стального кора.', 'Омыртқа тұрақтылығын және кор бұлшықеттерін нығайтатын негізгі статикалық жаттығу.', 'Transverse Abdominis, Rectus Abdominis, Core', 'Transverse Abdominis, Rectus Abdominis, Core', 'Поперечная мышца живота, прямая мышца, мышцы кора', 'Көлденең іш бұлшықеті, тік іш бұлшықеті, кор', 'Bodyweight / Mat', 'Bodyweight / Mat', 'Свой вес / коврик', 'Өз салмағы / төсеніш', 'Beginner', '1. Squeeze glutes and pull navel to spine to lock in a posterior pelvic tilt.
2. Maintain a rigid straight line connecting ears, shoulders, hips, and heels.
3. Push the floor away through forearms to avoid sagging between shoulder blades.
4. Hold for target duration with steady breathing.', '1. Сожмите ягодицы и подтяните пупок к позвоночнику для фиксации поясницы.
2. Удерживайте прямую линию: уши, плечи, таз и пятки на одной оси.
3. Активно выталкивайте грудной отдел вверх, не проваливаясь в лопатках.
4. Удерживайте планку намеченное время при ровном дыхании.', '1. Бөксені қатайтып, белді түзу ұстаңыз.
2. Бас, иық, жамбас және өкшені бір түзу сызық бойында ұстаңыз.
3. Жауырынның салбырап кетпеуін қадағалап, шынтақпен еденді итеріңіз.
4. Бірқалыпты тыныс алып, белгіленген уақыт бойы ұстап тұрыңыз.', 'Sagging hips into lumbar hyperextension, piking hips up in the air, dropping head downward.', 'Провисание таза в пояснице, задирание таза вверх домиком, опускание головы вниз.', 'Белдің төмен түсіп салбырауы, жамбасты жоғары көтеріп кету, басты төмен түсіру.', 'ASdvN_XEl_c', 'https://www.youtube.com/watch?v=ASdvN_XEl_c', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (27, 18, 'Barbell Hip Thrust', 'barbell_hip_thrust', 'Barbell Hip Thrust', 'Ягодичный мостик со штангой от скамьи', 'Орындықтан штангамен бөксе көтеру', 'The gold standard exercise for maximum gluteus maximus hypertrophy and hip extension power.', 'The gold standard exercise for maximum gluteus maximus hypertrophy and hip extension power.', 'Золотой стандарт для развития максимальной силы, объема и формы ягодичных мышц.', 'Бөксе бұлшықеттерінің күші мен көлемін арттыруға арналған ең үздік базалық жаттығу.', 'Gluteus Maximus', 'Gluteus Maximus', 'Большая ягодичная мышца', 'Үлкен бөксе бұлшықеті', 'Barbell & Bench (with pad)', 'Barbell & Bench (with pad)', 'Штанга и скамья (с подушкой)', 'Штанга және орындық (жастықшасымен)', 'Intermediate', '1. Keep chin tucked and gaze forward at your knees.
2. Drive through heels and extend hips upward until thighs and torso form a flat horizontal bridge.
3. Squeeze glutes hard at top lockout for 1-2 seconds with posterior pelvic tilt.
4. Lower hips under control until almost touching floor.', '1. Прижмите подбородок к груди, взгляд вперед перед собой.
2. Мощно оттолкнитесь пятками и поднимите таз вверх до горизонтального моста.
3. В верхней точке максимально сожмите ягодицы на 1-2 секунды.
4. Плавно опустите таз вниз, контролируя движение.', '1. Иекті кеудеге жақындатып, алға қараңыз.
2. Өкшемен күшпен итеріліп, дене көлденең түзу сызық болғанша жамбасты көтеріңіз.
3. Жоғарғы нүктеде бөксені 1-2 секунд қатайтып ұстаңыз.
4. Жамбасты баяу төмен түсіріңіз.', 'Hyperextending lumbar spine at top looking at ceiling, placing feet too close or too far away, lifting heels.', 'Прогиб в пояснице вверху с запрокидыванием головы, неправильная постановка стоп, отрыв пяток.', 'Белді қайқайту, басты артқа шалқайту, өкшені көтеру.', 'SEdqd1n0cvg', 'https://www.youtube.com/watch?v=SEdqd1n0cvg', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (28, 18, 'Bulgarian Split Squat', 'bulgarian_split_squat', 'Bulgarian Split Squat', 'Болгарские сплит-приседания', 'Болгарлық сплит-отыру', 'High-yield unilateral leg builder developing single-leg strength, glute hypertrophy, and hip stability.', 'High-yield unilateral leg builder developing single-leg strength, glute hypertrophy, and hip stability.', 'Мощнейшее одностороннее упражнение для гипертрофии ягодиц, ног и устранения мышечного дисбаланса.', 'Аяқтардың бұлшықет теңгерімсіздігін жоюға және бөксе көлемін арттыруға арналған жаттығу.', 'Gluteus Maximus, Quadriceps', 'Gluteus Maximus, Quadriceps', 'Большая ягодичная, квадрицепс', 'Үлкен бөксе, квадрицепс', 'Dumbbells & Bench', 'Dumbbells & Bench', 'Гантели и скамья', 'Гантельдер және орындық', 'Intermediate', '1. Descend under control by bending front knee until front thigh is parallel to floor.
2. Allow front knee to travel slightly forward naturally over toes.
3. Drive through midfoot and heel of front foot to return to top.
4. Complete all reps on one leg before switching.', '1. Плавно опуститесь вниз, сгибая переднее колено до параллели бедра с полом.
2. Сохраняйте основной вес на передней ноге.
3. Мощно оттолкнитесь пяткой и серединой стопы передней ноги для подъема.
4. Выполните все повторения на одну ногу, затем смените сторону.', '1. Алдыңғы тізені бүгіп, сан еденге параллель болғанша баяу отырыңыз.
2. Барлық салмақты алдыңғы аяқта ұстаңыз.
3. Алдыңғы аяқтың өкшесімен күшпен итеріліп, жоғары көтеріліңіз.
4. Бір аяқпен толық орындап, сосын екінші аяққа ауысыңыз.', 'Knee caving inward (valgus collapse), leaning too far backward loading the rear leg, bouncing off the bench.', 'Завал переднего колена внутрь, сильное отклонение назад с перегрузкой задней ноги, отскок от скамьи.', 'Тізенің ішке қарай майысуы, артқы аяққа тым қатты салмақ салу, орындықтан серпілу.', '2C-uNgKwPLE', 'https://www.youtube.com/watch?v=2C-uNgKwPLE', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (29, 20, 'Nordic Hamstring Curl', 'nordic_hamstring_curl', 'Nordic Hamstring Curl', 'Нордические сгибания на бицепс бедра (Nordic Curl)', 'Норвегиялық аяқ бүгу (Nordic Curl)', 'Gold standard eccentric hamstring exercise scientifically proven to drastically reduce hamstring injuries.', 'Gold standard eccentric hamstring exercise scientifically proven to drastically reduce hamstring injuries.', 'Научно доказанное лучшее упражнение для защиты бицепса бедра от надрывов и максимальной эксцентрической силы.', 'Санның артқы бұлшықетін жарақаттан қорғауға арналған ғылыми дәлелденген үздік жаттығу.', 'Hamstrings (Eccentric Overload)', 'Hamstrings (Eccentric Overload)', 'Бицепс бедра (эксцентрическая нагрузка)', 'Санның артқы бұлшықеті (эксцентрикалық күш)', 'Bodyweight / Partner / Ankle Strap', 'Bodyweight / Partner / Ankle Strap', 'Свой вес / помощь партнера / фиксатор', 'Өз салмағы / серіктес көмегі / бекіткіш', 'Advanced', '1. Squeeze glutes and hamstrings, keeping hips locked straight.
2. Lower torso forward toward floor as slowly as possible using solely hamstring resistance.
3. Catch yourself with hands when hamstrings reach failure.
4. Lightly push off the floor and return to start.', '1. Сожмите ягодицы и пресс, зафиксировав таз в прямом положении.
2. Максимально медленно опускайте тело вперед к полу, сопротивляясь силой бицепсов бедер.
3. В конце движения мягко поймайте себя руками на пол.
4. Легким толчком рук помогите себе вернуться в исходную позицию.', '1. Бөксе мен корды қатайтып, жамбасты бүкпей түзу ұстаңыз.
2. Санның артқы бұлшықеттерінің күшімен денені барынша баяу алға түсіріңіз.
3. Соңында қолмен еденге жұмсақ тіреліңіз.
4. Қолмен сәл итеріліп, бастапқы қалыпқа оралыңыз.', 'Bending at the hips (breaking neutral hip line), dropping too fast without resistance, hyperextending neck.', 'Сгибание в тазобедренных суставах (излом прямой линии тела), быстрое падение вперед без сопротивления.', 'Жамбастан бүгіліп түзулікті бұзу, салмақты ұстамай тез құлап түсу.', 'd86sX_V3zP0', 'https://www.youtube.com/watch?v=d86sX_V3zP0', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (30, 24, 'Russian Kettlebell Swing', 'kettlebell_swing', 'Russian Kettlebell Swing', 'Махи гирей двумя руками (Kettlebell Swing)', 'Екі қолмен гир сермеу (Kettlebell Swing)', 'Explosive hip hinge developing posterior chain power, hip snap speed, and cardiovascular conditioning.', 'Explosive hip hinge developing posterior chain power, hip snap speed, and cardiovascular conditioning.', 'Мощное взрывное тазово-доминантное упражнение для развития взрывной силы бедер и кардиовыносливости.', 'Жамбастың жарылыс күшін және төзімділікті дамытатын негізгі функционалды жаттығу.', 'Glutes, Hamstrings, Core, Posterior Chain', 'Glutes, Hamstrings, Core, Posterior Chain', 'Ягодицы, бицепсы бедер, мышцы кора, спина', 'Бөксе, санның артқы жағы, кор, арқа', 'Kettlebell', 'Kettlebell', 'Гиря', 'Гир', 'Intermediate', '1. Hike kettlebell back between upper thighs like a football snap.
2. Drive hips forward explosively, snapping glutes into full vertical lockout.
3. Let kettlebell float to chest/eye level under hip momentum (arms act only as loose ropes).
4. Guide kettlebell back into hinge as it falls.', '1. Замахнитесь гирей назад между бедрами (как в американском футболе).
2. Мощно разогните таз вперед, сжав ягодицы в конечной вертикальной точке.
3. Позвольте гире взлететь до уровня груди по инерции (руки расслаблены как тросы).
4. Подхватите гирю бедрами при обратном движении.', '1. Гирді аяқтың арасынан артқа қарай сермеңіз.
2. Жамбасты алға қарай күшпен итеріп, бөксені тік қалыпта қатайтыңыз.
3. Гир екпінмен кеуде деңгейіне дейін көтерілуі керек (қолдар тек бағыттайды).
4. Гир төмен түскенде жамбаспен қайта сермеңіз.', 'Squatting instead of hinging hips, lifting with shoulders/arms instead of hips, rounding lower back.', 'Приседание вместо тазового наклона (хинджа), подъем гири руками и плечами, скругление поясницы.', 'Еңкеюдің орнына отырып қалу, гирді жамбаспен емес қолмен тарту, белді бүкірейту.', 'sSESeQAir2M', 'https://www.youtube.com/watch?v=sSESeQAir2M', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (31, 25, 'Rhythmic Jumping Jacks', 'jumping_jacks', 'Rhythmic Jumping Jacks', 'Прыжки Джампинг Джек (Jumping Jacks)', 'Джампинг Джек секіру жаттығуы (Jumping Jacks)', 'Classic full-body cardiovascular warm-up drill enhancing elasticity, rhythm, and heart rate.', 'Classic full-body cardiovascular warm-up drill enhancing elasticity, rhythm, and heart rate.', 'Классическое кардио-упражнение для разминки, повышения пульса и координации всего тела.', 'Денені қыздыруға, жүрек соғысын реттеуге және серпімділікті арттыруға арналған жаттығу.', 'Cardiovascular Endurance, Calves, Deltoids', 'Cardiovascular Endurance, Calves, Deltoids', 'Сердечно-сосудистая система, икры, дельты', 'Жүрек-қан тамырлары, балтыр, дельталар', 'Bodyweight', 'Bodyweight', 'Свой вес', 'Өз салмағы', 'Beginner', '1. Jump feet out wider than shoulder-width while raising arms overhead in a wide arc.
2. Land lightly and springily on the balls of your feet with knees soft.
3. Immediately jump feet back together while bringing arms back down.
4. Maintain a continuous, brisk rhythm.', '1. В прыжке расставьте ноги шире плеч, одновременно поднимая руки через стороны над головой.
2. Приземляйтесь мягко на носки со слегка согнутыми коленями.
3. Вторым прыжком вернитесь в исходное положение.
4. Сохраняйте непрерывный бодрый темп.', '1. Секіріп аяқты иықтан кең қойып, қолды екі жақпен жоғары көтеріңіз.
2. Тізені сәл бүгіп, аяқтың ұшына жұмсақ түсіңіз.
3. Қайта секіріп, аяқ пен қолды бастапқы қалыпқа жинаңыз.
4. Үздіксіз ырғақты сақтаңыз.', 'Landing flat-footed with loud impact, stiff locked knees, flailing arms without control.', 'Жесткое приземление на всю стопу (удар по суставам), прямые колени, раскоординированные взмахи.', 'Өкшемен қатты түсу, тізені бүкпеу, қолды ретсіз сермеу.', 'iSSAk4XCsRA', 'https://www.youtube.com/watch?v=iSSAk4XCsRA', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (32, 26, 'Worlds Greatest Stretch', 'worlds_greatest_stretch', 'World''s Greatest Stretch', 'Величайшая растяжка в мире (World''s Greatest Stretch)', 'Әлемдегі ең үздік созылу жаттығуы (World''s Greatest Stretch)', 'The pinnacle full-body dynamic mobility flow opening hips, ankles, and thoracic spine rotation.', 'The pinnacle full-body dynamic mobility flow opening hips, ankles, and thoracic spine rotation.', 'Лучший комплексный комплекс динамической растяжки для раскрытия тазобедренных суставов и мобильности грудного отдела.', 'Жамбас буындары мен кеуде омыртқасының қозғалғыштығын ашатын ең үздік кешенді созылу жаттығуы.', 'Thoracic Spine, Hip Flexors, Hamstrings, Adductors', 'Thoracic Spine, Hip Flexors, Hamstrings, Adductors', 'Грудной отдел позвоночника, сгибатели бедра, бицепс бедра', 'Кеуде омыртқасы, жамбас бұлшықеттері, санның артқы жағы', 'Bodyweight / Mat', 'Bodyweight / Mat', 'Свой вес / коврик', 'Өз салмағы / төсеніш', 'Beginner', '1. Drop right elbow down inside right instep, holding for a deep hip flexor stretch.
2. Rotate chest and right arm up toward the ceiling, gazing at your hand.
3. Return hand to floor, shift hips backward to straighten front leg into a hamstring stretch.
4. Return to plank and repeat on opposite side.', '1. Опустите правый локоть вниз к внутренней части стопы, почувствуйте растяжение бедер.
2. Разверните грудную клетку и правую руку вверх к потолку, взгляд за рукой.
3. Опустите руку на пол, отведите таз назад и выпрямите переднюю ногу (растяжка задней поверхности).
4. Вернитесь в планку и повторите на левую сторону.', '1. Оң шынтақты оң табанның ішкі жағына түсіріп, жамбасты созыңыз.
2. Кеудені және оң қолды жоғары төбеге қарай бұрып, қолға қараңыз.
3. Қолды еденге қойып, жамбасты артқа жылжытып, алдыңғы аяқты созыңыз.
4. Планкаға оралып, екінші жаққа қайталаңыз.', 'Rushing through positions, letting back knee collapse heavily onto floor, avoiding deep breathing.', 'Спешка без фиксации точек, падение заднего колена на пол, задержка дыхания.', 'Асығыс жасау, артқы тізені еденге құлату, тынысты ұстау.', '8z5R4x6YV4s', 'https://www.youtube.com/watch?v=8z5R4x6YV4s', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (33, 1, 'Resistance Band Push-up', 'resistance_band_pushup', 'Resistance Band Push-up', 'Отжимания с фитнес-резинкой', 'Резеңке таспамен сығылу', 'Accommodating resistance push-up increasing pectoral lockout tension.', 'Accommodating resistance push-up increasing pectoral lockout tension.', 'Отжимания с дополнительным нарастающим сопротивлением резиновой ленты в верхней точке.', 'Жоғарғы нүктеде кеудеге түсетін салмақты арттыратын резеңкемен сығылу.', 'Pectoralis Major, Triceps Brachii', 'Pectoralis Major, Triceps Brachii', 'Большая грудная, трицепс', 'Үлкен кеуде бұлшықеті, трицепс', 'Resistance Band', 'Resistance Band', 'Фитнес-резинка', 'Резеңке таспа', 'Intermediate', '1. Lower chest under control to floor against reducing band tension.
2. Drive powerfully upward through increasing band resistance to full lockout.
3. Keep core rigid throughout.', '1. Плавно опуститесь к полу.
2. Мощно выжмите себя вверх против возрастающего сопротивления ленты.
3. Держите корпус ровно.', '1. Кеудені еденге баяу түсіріңіз.
2. Резеңке қарсылығына қарсы жоғары қарай күшпен итеріліңіз.
3. Денені түзу ұстаңыз.', 'Sagging hips, letting band slip off back.', 'Провисание таза, соскальзывание ленты.', 'Белдің салбырауы, резеңкенің сырғып кетуі.', 'IODxDxX7oi4', 'https://www.youtube.com/watch?v=IODxDxX7oi4', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (34, 2, 'Seated Cable Row', 'seated_cable_row', 'Seated Cable Row', 'Горизонтальная тяга блока к поясу сидя', 'Отырып блокты белге тарту', 'Horizontal pulling machine exercise developing dense mid-back musculature and scapular retraction.', 'Horizontal pulling machine exercise developing dense mid-back musculature and scapular retraction.', 'Базовое движение на блоке для развития толщины середины спины и ровной осанки.', 'Арқаның ортаңғы бөлігін қалыңдатуға және жауырынды жиыруға арналған жаттығу.', 'Rhomboids, Latissimus Dorsi, Middle Trapezius', 'Rhomboids, Latissimus Dorsi, Middle Trapezius', 'Ромбовидные, широчайшие, средняя трапеция', 'Ромб тәрізді, жалпақ бұлшықеттер, трапеция', 'Seated Cable Row Machine', 'Seated Cable Row Machine', 'Блочный тренажер горизонтальной тяги', 'Көлденең блокты тарту тренажеры', 'Beginner', '1. Pull handle into lower abdomen while driving elbows back.
2. Retract shoulder blades firmly and pause 1 second.
3. Release slowly forward to a full lat stretch without excessive forward rounding.', '1. Тяните рукоять к низу живота, уводя локти назад.
2. Мощно сведите лопатки и удержите 1 секунду.
3. Плавно вернитесь вперед до растяжения широчайших.', '1. Шынтақты артқа бағыттап, тұтқаны іштің төменгі жағына тартыңыз.
2. Жауырынды 1 секунд жиырып ұстаңыз.
3. Қолды баяу алға созып бастапқы қалыпқа қайтыңыз.', 'Rocking excessively back and forth with lower back, shrugging shoulders up.', 'Сильная раскачка корпусом вперед-назад, подъем плеч к ушам.', 'Денемен алға-артқа қатты шайқалу, иықты көтеру.', 'GZbfZ033f74', 'https://www.youtube.com/watch?v=GZbfZ033f74', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (35, 6, 'Dumbbell Arnold Press', 'arnold_press', 'Dumbbell Arnold Press', 'Жим Арнольда с гантелями', 'Арнольд жимі (гантельмен)', 'Rotational overhead shoulder press hitting anterior and lateral deltoid heads.', 'Rotational overhead shoulder press hitting anterior and lateral deltoid heads.', 'Жимовое упражнение с вращением кистей для комплексной проработки всех пучков дельт.', 'Қолды айналдыра көтеретін иықтың барлық бөліктерін дамытатын жаттығу.', 'Anterior & Lateral Deltoids', 'Anterior & Lateral Deltoids', 'Передняя и средняя дельтовидные мышцы', 'Алдыңғы және ортаңғы дельталар', 'Dumbbells & Bench', 'Dumbbells & Bench', 'Гантели и скамья', 'Гантельдер және орындық', 'Intermediate', '1. Press dumbbells upward while rotating wrists outwards 180 degrees.
2. At top lockout, palms face forward.
3. Reverse rotation smoothly on descent back to starting position.', '1. Выжимайте гантели вверх, одновременно разворачивая кисти наружу на 180°.
2. В верхней точке ладони смотрят вперед.
3. Плавно вернитесь вниз с обратным разворотом кистей.', '1. Гантельдерді жоғары көтере отырып, білекті 180 градусқа сыртқа бұрыңыз.
2. Жоғарғы нүктеде алақан алға қарайды.
3. Бастапқы қалыпқа баяу қайтыңыз.', 'Jerking dumbbells, overarching lower back, rotating too late at the top.', 'Резкие рывки, сильный прогиб в пояснице, запоздалый разворот кистей.', 'Жұлқып көтеру, белді қайқайту, білекті кеш бұру.', '2yjwHevKmT0', 'https://www.youtube.com/watch?v=2yjwHevKmT0', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (36, 19, 'Dumbbell Goblet Squat', 'goblet_squat', 'Dumbbell Goblet Squat', 'Гоблет-приседания с гантелью / гирей', 'Гоблет-отыру (гантельмен / гирмен)', 'Front-loaded squat variation reinforcing upright torso mechanics and deep hip mobility.', 'Front-loaded squat variation reinforcing upright torso mechanics and deep hip mobility.', 'Отличное упражнение для отработки глубокого приседа с вертикальной спиной и подвижности таза.', 'Арқаны тік ұстап терең отыруды үйрететін тиімді жаттығу.', 'Quadriceps, Glutes, Core Stabilizers', 'Quadriceps, Glutes, Core Stabilizers', 'Квадрицепсы, ягодицы, кор', 'Квадрицепстер, бөксе, кор', 'Dumbbell / Kettlebell', 'Dumbbell / Kettlebell', 'Гантель / гиря', 'Гантель / гир', 'Beginner', '1. Sit down between knees, keeping chest tall and elbows inside knees at bottom.
2. Descend until thighs pass parallel.
3. Drive through midfoot to stand up tall.', '1. Опускайтесь вниз между коленями, держа спину вертикально.
2. Присядьте до параллели или глубже.
3. Оттолкнитесь стопами и вернитесь вверх.', '1. Арқаны тік ұстап, тізелер арасына қарай отырыңыз.
2. Сан параллельден төмен түскенше отырыңыз.
3. Табанмен итеріліп, тік тұрыңыз.', 'Rounding upper back, letting elbows flare outside knees, rising onto toes.', 'Скругление спины, завал на носки, сведение коленей.', 'Арқаны бүкірейту, өкшені көтеру, тізені ішке майыстыру.', 'aclH2T8NY5I', 'https://www.youtube.com/watch?v=aclH2T8NY5I', TRUE, TRUE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (37, 19, 'Leg Extension Machine', 'leg_extension_machine', 'Leg Extension Machine', 'Разгибание ног в тренажере сидя', 'Тренажерде отырып аяқты жазу (квадрицепс)', 'Pure isolated knee extension focusing high tension on all 4 quadriceps heads.', 'Pure isolated knee extension focusing high tension on all 4 quadriceps heads.', 'Изолированное упражнение на тренажере для детальной прорисовки и накачки квадрицепсов.', 'Квадрицепсті оқшаулап қатайтуға және пішінін айқындауға арналған тренажер жаттығуы.', 'Quadriceps (Direct Isolation)', 'Quadriceps (Direct Isolation)', 'Квадрицепсы (изолированная нагрузка)', 'Квадрицепстер (оқшауланған күш)', 'Leg Extension Machine', 'Leg Extension Machine', 'Тренажер для разгибания ног', 'Аяқты жазу тренажеры', 'Beginner', '1. Grip handles on the sides.
2. Extend legs smoothly until knees are nearly fully extended.
3. Hold peak contraction for 1 second.
4. Lower weight under 2-second control without letting stack slam.', '1. Возьмитесь за боковые рукояти.
2. Разгибайте ноги вверх силой квадрицепсов.
3. Зафиксируйте пиковое напряжение вверху на 1 секунду.
4. Плавно опустите ноги за 2 секунды.', '1. Бүйірлік тұтқаларды ұстаңыз.
2. Квадрицепс күшімен аяқты жоғары қарай толық жазыңыз.
3. Жоғарғы нүктеде 1 секунд қатайтып ұстаңыз.
4. Баяу төмен түсіріңіз.', 'Kicking weight up with momentum, lifting hips off seat, slamming weights.', 'Резкие рывки ногами, отрыв таза от сиденья, бросок веса.', 'Аяқты сермеп көтеру, бөксені орындықтан көтеру, салмақты тастай салу.', 'YyvSfV510ok', 'https://www.youtube.com/watch?v=YyvSfV510ok', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;

INSERT INTO public.exercises (id, category_id, name, slug, name_en, name_ru, name_kk, description, description_en, description_ru, description_kk, target_muscle, target_muscles_en, target_muscles_ru, target_muscles_kk, equipment, equipment_en, equipment_ru, equipment_kk, difficulty, instructions_en, instructions_ru, instructions_kk, common_mistakes_en, common_mistakes_ru, common_mistakes_kk, youtube_id, video_url, analysis_supported, analysis_available)
VALUES (38, 25, 'Speed Mountain Climbers', 'mountain_climbers', 'Speed Mountain Climbers', 'Упражнение Скалолаз (Mountain Climbers)', 'Тауға өрмелеуші жаттығуы (Mountain Climbers)', 'High-intensity dynamic plank exercise boosting cardiovascular conditioning and core endurance.', 'High-intensity dynamic plank exercise boosting cardiovascular conditioning and core endurance.', 'Динамическое упражнение в планке для интенсивного сжигания калорий и укрепления пресса.', 'Жүрек соғысын жеделдетуге және іш бұлшықеттерін қатайтуға арналған қарқынды планка жаттығуы.', 'Cardiovascular Endurance, Core, Hip Flexors', 'Cardiovascular Endurance, Core, Hip Flexors', 'Сердечно-сосудистая система, кор, сгибатели бедер', 'Жүрек-қан тамырлары, кор, жамбас бұлшықеттері', 'Bodyweight', 'Bodyweight', 'Свой вес', 'Өз салмағы', 'Beginner', '1. Drive right knee rapidly forward toward chest without letting hips bounce up.
2. Quickly switch legs in a running cadence, driving left knee forward as right returns.
3. Maintain rapid, rhythmic pace while keeping shoulders stable over hands.', '1. Быстро подтяните правое колено к груди, не задирая таз вверх.
2. В прыжке смените ноги, подтягивая левое колено к груди.
3. Сохраняйте быстрый непрерывный беговой ритм, удерживая плечи над ладонями.', '1. Жамбасты көтермей, оң тізені кеудеге қарай жылдам тартыңыз.
2. Аяқтарды кезек-кезек ауыстырып, жүгіру ырғағымен сол тізені тартыңыз.
3. Денені түзу ұстап, қарқынды ырғақты сақтаңыз.', 'Piking hips up toward ceiling, bouncing upper body, letting hands slide forward.', 'Задирание таза вверх домиком, подпрыгивание корпусом, увод плеч назад от ладоней.', 'Жамбасты жоғары көтеріп кету, денені селкілдету.', 'nmwgirgXLYM', 'https://www.youtube.com/watch?v=nmwgirgXLYM', FALSE, FALSE)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, name_ru = EXCLUDED.name_ru, name_kk = EXCLUDED.name_kk, description_en = EXCLUDED.description_en, description_ru = EXCLUDED.description_ru, description_kk = EXCLUDED.description_kk, target_muscles_en = EXCLUDED.target_muscles_en, target_muscles_ru = EXCLUDED.target_muscles_ru, target_muscles_kk = EXCLUDED.target_muscles_kk, instructions_en = EXCLUDED.instructions_en, instructions_ru = EXCLUDED.instructions_ru, instructions_kk = EXCLUDED.instructions_kk, youtube_id = EXCLUDED.youtube_id, video_url = EXCLUDED.video_url, analysis_supported = EXCLUDED.analysis_supported;
